package com.example.library;
import com.example.library.entity.*;import com.example.library.dto.*;import com.example.library.repository.*;import com.example.library.service.*;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.mock.mockito.SpyBean;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.web.servlet.MockMvc;import org.springframework.security.test.context.support.WithMockUser;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.MediaType;
import java.util.*;import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:payos_test;DB_CLOSE_DELAY=-1","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=","spring.jpa.database-platform=org.hibernate.dialect.H2Dialect","spring.jpa.hibernate.ddl-auto=create-drop","app.seed.enabled=false","app.payos.client-id=test-client","app.payos.api-key=test-api","app.payos.checksum-key=1a54716c8f0efb2744fb28b6e38b25da7f67a925d98bc1c18bd8faaecadd7675"})
@AutoConfigureMockMvc @Transactional @org.springframework.test.context.event.RecordApplicationEvents
class PayosIntegrationTest {
 @Autowired BorrowCheckoutService checkout;@Autowired PayosPaymentService service;@SpyBean PayosGateway gateway;@Autowired UserRepository users;@Autowired BookRepository books;@Autowired BookCopyService inventory;@Autowired BorrowPaymentRepository payments;@Autowired LoanRepository loans;@Autowired ObjectMapper json;@Autowired MockMvc mvc;
 @Autowired org.springframework.test.context.event.ApplicationEvents events;
 Book book;LoanCreateRequest request;
 @BeforeEach void setup(){users.save(User.builder().email("payer@test.com").fullName("Payer").password("unused").build());book=books.save(Book.builder().title("Java").totalQuantity(2).availableQuantity(2).status(BookStatus.AVAILABLE).rentalPrice(new BigDecimal("10000")).salePrice(new BigDecimal("50000")).build());inventory.initialize(book.getId());var item=new LoanItemRequest();item.setBookId(book.getId());item.setQuantity(2);request=new LoanCreateRequest();request.setPolicyAccepted(true);request.setPolicyVersion(BorrowingPolicy.VERSION);request.setDays(28);request.setItems(List.of(item));}
 BorrowPayment order(){return checkout.preparePayos("payer@test.com",request,"payos-key-12345678");}
 JsonNode state(BorrowPayment p,String status){var d=json.createObjectNode();d.put("orderCode",gateway.orderCode(p));d.put("amount",p.getAmount().longValueExact());d.put("amountPaid",status.equals("PAID")?p.getAmount().longValueExact():0);d.put("id","123456789012345678901234567890ab");d.put("status",status);return d;}
 JsonNode webhook(BorrowPayment p){var d=json.createObjectNode();d.put("orderCode",gateway.orderCode(p));d.put("amount",p.getAmount().longValueExact());d.put("code","00");d.put("currency","VND");var envelope=json.createObjectNode();envelope.set("data",d);envelope.put("signature",gateway.sign(d));return envelope;}
 @Test void officialSignatureFixtureMatchesPublishedVector()throws Exception{var d=json.readTree("""
 {"orderCode":123,"amount":3000,"description":"VQRIO123","accountNumber":"12345678","reference":"TF230204212323","transactionDateTime":"2023-02-04 18:25:00","currency":"VND","paymentLinkId":"124c33293c43417ab7879e14c8d9eb18","code":"00","desc":"Thành công","counterAccountBankId":"","counterAccountBankName":"","counterAccountName":"","counterAccountNumber":"","virtualAccountName":"","virtualAccountNumber":""}
 """);assertEquals("412e915d2871504ed31be63c8f62a149a4410d34c4c42affc9006ef9917eaa03",gateway.sign(d));}
 @Test void retryUsesSameOrderAndCurrentRentalPricing(){var p=order();assertEquals(p.getId(),order().getId());assertEquals(new BigDecimal("40000"),p.getAmount());assertEquals(1,payments.count());assertEquals(0,loans.count());}
 @Test void duplicatedVerifiedWebhookCreatesOneLoan(){var p=order();doReturn(state(p,"PAID")).when(gateway).lookup(any());service.webhook(webhook(p));service.webhook(webhook(p));assertEquals(1,loans.count());var emails=events.stream(ReaderEmail.class).toList();assertEquals(1,emails.size());assertEquals("payer@test.com",emails.getFirst().recipient());assertTrue(emails.getFirst().body().contains(p.getId()));assertEquals("PAID",payments.findById(p.getId()).orElseThrow().getStatus());assertEquals(0,book.getAvailableQuantity());}
 @Test void forgedWebhookCannotCreateLoan(){var p=order();var body=(com.fasterxml.jackson.databind.node.ObjectNode)webhook(p);body.put("signature","0".repeat(64));assertThrows(IllegalArgumentException.class,()->service.webhook(body));assertEquals(0,loans.count());verify(gateway,never()).lookup(any());}
 @Test void signedWrongAmountDoesNotAllocateBooks(){var p=order();var d=(com.fasterxml.jackson.databind.node.ObjectNode)state(p,"PAID");d.put("amount",1);assertThrows(IllegalArgumentException.class,()->checkout.reconcilePayos(p.getId(),d));assertEquals(0,loans.count());}
 @Test void stockUnavailableIsRecordedForReview(){var p=order();inventory.take(book.getId(),1,BookCopyStatus.BORROWED);checkout.reconcilePayos(p.getId(),state(p,"PAID"));assertEquals("REVIEW_REQUIRED",p.getStatus());assertEquals(0,loans.count());}
 @Test void canceledThenLatePaymentNeedsManualReview(){var p=order();checkout.reconcilePayos(p.getId(),state(p,"CANCELLED"));assertEquals("FAILED",p.getStatus());checkout.reconcilePayos(p.getId(),state(p,"PAID"));assertEquals("REVIEW_REQUIRED",p.getStatus());assertEquals(0,loans.count());}
 @Test void remoteTimeoutKeepsPendingOrderForRetry(){doThrow(new IllegalStateException("timeout")).when(gateway).create(any());assertThrows(IllegalStateException.class,()->service.create("payer@test.com",request,"payos-key-12345678"));assertEquals("PENDING",order().getStatus());assertEquals(1,payments.count());}
 @Test void ownerCanSyncPaidState(){var p=order();doReturn(state(p,"PAID")).when(gateway).lookup(any());service.sync(p.getId(),"payer@test.com");assertEquals("PAID",p.getStatus());assertEquals(1,loans.count());}
 @Test void otherAccountCannotReadOrSync(){var p=order();assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.sync(p.getId(),"other@test.com"));verify(gateway,never()).lookup(any());}
 @Test void expiredLocalPendingStillBlocksCashUntilProviderConfirms(){var p=order();p.setExpiresAt(p.getCreatedAt().minusMinutes(1));assertThrows(IllegalStateException.class,()->checkout.cashCheckout("payer@test.com",request,"cash-other-123456"));assertEquals(0,loans.count());}
 @Test void signedRegistrationExampleIsAcknowledgedWithoutLoan()throws Exception{var p=order();var body=(com.fasterxml.jackson.databind.node.ObjectNode)webhook(p);var d=(com.fasterxml.jackson.databind.node.ObjectNode)body.get("data");d.put("orderCode",123);body.put("signature",gateway.sign(d));mvc.perform(post("/api/v1/payments/payos/webhook").contentType(MediaType.APPLICATION_JSON).content(body.toString())).andExpect(status().isOk());assertEquals(0,loans.count());}
 @Test void anonymousCannotCreateCheckout()throws Exception{mvc.perform(post("/api/v1/payments/payos/checkout").header("Idempotency-Key","payos-key-12345678").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(request))).andExpect(status().isUnauthorized());assertEquals(0,payments.count());}
 @Test void redirectRejectsUntrustedHost(){assertThrows(IllegalStateException.class,()->gateway.checkoutUrl(json.createObjectNode().put("checkoutUrl","https://evil.example/path")));}
 @Test void missingConfigurationFailsBeforeCreatingOrder(){var empty=new PayosGateway(json);org.springframework.test.util.ReflectionTestUtils.setField(empty,"clientId","");org.springframework.test.util.ReflectionTestUtils.setField(empty,"apiKey","");org.springframework.test.util.ReflectionTestUtils.setField(empty,"checksumKey","");var isolated=new PayosPaymentService(checkout,empty,payments);assertThrows(IllegalStateException.class,()->isolated.create("payer@test.com",request,"payos-key-12345678"));assertEquals(0,payments.count());}
 @Test void resumeUsesExistingOrderWithoutNewPayment(){var p=order();doReturn(state(p,"PENDING")).when(gateway).lookup(any());doReturn(state(p,"PENDING")).when(gateway).create(any());var result=service.resume(p.getId(),"payer@test.com");assertEquals(p.getId(),result.get("id"));assertEquals(1,payments.count());assertTrue(result.get("url").toString().startsWith("https://pay.payos.vn/web/"));}
 @Test void resumeRejectsOtherOwner(){var p=order();assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.resume(p.getId(),"other@test.com"));verify(gateway,never()).create(any());}
 @Test void canceledLinkCanResumeWithNewOrderAndRetryDoesNotDuplicate(){var original=order();doReturn(state(original,"CANCELLED")).when(gateway).lookup(original);doAnswer(invocation->state(invocation.getArgument(0),"PENDING")).when(gateway).create(any());var first=service.resume(original.getId(),"payer@test.com");var second=service.resume(original.getId(),"payer@test.com");assertNotEquals(original.getId(),first.get("id"));assertEquals(first.get("id"),second.get("id"));assertEquals("FAILED",original.getStatus());assertEquals(2,payments.count());assertEquals(0,loans.count());assertEquals("retry-"+original.getId(),first.get("requestKey"));}
 @Test void partiallyPaidCanceledOrderCannotBeRetried(){var p=order();var remote=(com.fasterxml.jackson.databind.node.ObjectNode)state(p,"CANCELLED");remote.put("amountPaid",1000);doReturn(remote).when(gateway).lookup(p);assertThrows(IllegalStateException.class,()->service.resume(p.getId(),"payer@test.com"));assertEquals("REVIEW_REQUIRED",p.getStatus());assertEquals(1,payments.count());verify(gateway,never()).create(any());}
 @Test void retryRejectsChangedPriceAndPreservesOriginalSnapshot(){var p=order();doReturn(state(p,"CANCELLED")).when(gateway).lookup(p);book.setRentalPrice(new BigDecimal("11000"));assertThrows(IllegalStateException.class,()->service.resume(p.getId(),"payer@test.com"));assertEquals(1,payments.count());assertEquals(28,checkout.payosOrder(p.getId(),"payer@test.com").getDays());}
 @Test void snapshotRejectsAnotherReader(){var p=order();assertThrows(org.springframework.security.access.AccessDeniedException.class,()->checkout.payosOrder(p.getId(),"other@test.com"));}
 @Test void explicitCancelEndsRequestAndAllowsCashOrder(){var p=order();doReturn(state(p,"PENDING")).when(gateway).lookup(p);doReturn(state(p,"CANCELLED")).when(gateway).cancel(p);service.cancel(p.getId(),"payer@test.com");assertEquals("CANCELLED",p.getStatus());assertEquals(0,loans.count());var cash=checkout.cashCheckout("payer@test.com",request,"new-cash-after-cancel");assertNotNull(cash.get("loanId"));assertEquals(1,loans.count());}
 @Test void explicitCancelOfPreviouslyCanceledLinkDoesNotCallCancelAgain(){var p=order();doReturn(state(p,"CANCELLED")).when(gateway).lookup(p);service.cancel(p.getId(),"payer@test.com");service.cancel(p.getId(),"payer@test.com");assertEquals("CANCELLED",p.getStatus());verify(gateway,never()).cancel(any());assertThrows(IllegalStateException.class,()->service.resume(p.getId(),"payer@test.com"));}
 @Test void cannotCancelPaidOrPartiallyPaidPayment(){var p=order();var data=(com.fasterxml.jackson.databind.node.ObjectNode)state(p,"PENDING");data.put("amountPaid",1000);doReturn(data).when(gateway).lookup(p);assertThrows(IllegalStateException.class,()->service.cancel(p.getId(),"payer@test.com"));verify(gateway,never()).cancel(any());assertEquals("PENDING",p.getStatus());}
 @Test void failedCancelKeepsOrderPendingAndBlocksCash(){var p=order();doReturn(state(p,"PENDING")).when(gateway).lookup(p);doThrow(new IllegalStateException("cancel failed")).when(gateway).cancel(p);assertThrows(IllegalStateException.class,()->service.cancel(p.getId(),"payer@test.com"));assertEquals("PENDING",p.getStatus());assertThrows(IllegalStateException.class,()->checkout.cashCheckout("payer@test.com",request,"cash-block-after-fail"));}
 @Test void cannotCancelOtherReaderPayment(){var p=order();assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.cancel(p.getId(),"other@test.com"));verify(gateway,never()).lookup(any());}

 @Test @WithMockUser(username="payer@test.com",roles="USER") void newCheckoutRequiresPolicyConsentAndSavesVersion()throws Exception{
  request.setPolicyAccepted(false);for(String path:List.of("/api/v1/payments/cash","/api/v1/payments/payos/checkout","/api/v1/payments/checkout","/api/v1/loans")){mvc.perform(post(path).header("Idempotency-Key","consent-check-123456").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(request))).andExpect(status().isBadRequest());}assertEquals(0,payments.count());assertEquals(0,loans.count());
  request.setPolicyAccepted(true);request.setPolicyVersion("old-version");mvc.perform(post("/api/v1/payments/cash").header("Idempotency-Key","consent-check-123456").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(request))).andExpect(status().isBadRequest());
  request.setPolicyVersion(BorrowingPolicy.VERSION);request.setDays(17);mvc.perform(post("/api/v1/payments/cash").header("Idempotency-Key","consent-check-123456").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(request))).andExpect(status().isOk()).andExpect(jsonPath("$.amount").value(24286));
  var saved=payments.findAll().get(0);assertTrue(json.readTree(saved.getRequestJson()).path("policyAccepted").asBoolean());assertEquals(BorrowingPolicy.VERSION,json.readTree(saved.getRequestJson()).path("policyVersion").asText());assertNotNull(saved.getCreatedAt());
 }

 @Autowired AuthService authService;
 @Autowired org.springframework.security.crypto.password.PasswordEncoder passwordEncoder;

 @Test void successfulPasswordChangePublishesEmailWithoutPassword() {
  var user=users.findByEmail("payer@test.com").orElseThrow();
  user.setPassword(passwordEncoder.encode("old-password"));
  users.saveAndFlush(user);
  authService.changePassword(user.getEmail(), "old-password", "new-password");
  var emails=events.stream(ReaderEmail.class).toList();
  assertEquals(1,emails.size());
  assertEquals(user.getEmail(),emails.getFirst().recipient());
  assertFalse(emails.getFirst().body().contains("new-password"));
  assertTrue(passwordEncoder.matches("new-password",user.getPassword()));
 }
}
